    public String taoMaMoi(){String q="SELECT MAX(TRY_CONVERT(INT,SUBSTRING(maLichHen,3,18))) FROM LichHen WHERE maLichHen LIKE 'LH[0-9]%'";try(Connection c=ConnectDB.getConnection();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){int n=0;if(r.next())n=r.getInt(1);return String.format(java.util.Locale.ROOT,"LH%02d",n+1);}catch(SQLException e){throw new IllegalStateException("Không thể phát sinh mã lịch hẹn: "+e.getMessage(),e);}}
    private List<String> layMa(String sql){List<String> a=new ArrayList<>();try(Connection c=ConnectDB.getConnection();PreparedStatement p=c.prepareStatement(sql);ResultSet r=p.executeQuery()){while(r.next())a.add(r.getString(1));}catch(SQLException e){throw new IllegalStateException("Không thể tải dữ liệu liên quan: "+e.getMessage(),e);}return a;}
    public boolean them(LichHen l){String sql="INSERT INTO LichHen(maLichHen,thoiGianHen,trangThai,maNV,maKH,maThuCung) VALUES(?,?,?,?,?,?)";try(Connection c=ConnectDB.getConnection();PreparedStatement p=c.prepareStatement(sql)){gan(p,l,false);return p.executeUpdate()>0;}catch(SQLException e){throw new IllegalStateException("Không thể thêm lịch hẹn: "+e.getMessage(),e);}}
    public boolean capNhat(LichHen l){String sql="UPDATE LichHen SET thoiGianHen=?,trangThai=?,maNV=?,maKH=?,maThuCung=? WHERE maLichHen=? AND trangThai <> N'Đã xóa'";try(Connection c=ConnectDB.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setTimestamp(1,Timestamp.valueOf(l.getThoiGianHen()));p.setString(2,l.getTrangThai());p.setString(3,l.getMaNV().getMaNV());p.setString(4,l.getMaKH().getMaKH());p.setString(5,l.getMaThuCung().getMaThuCung());p.setString(6,l.getMaLichHen());return p.executeUpdate()>0;}catch(SQLException e){throw new IllegalStateException("Không thể cập nhật lịch hẹn: "+e.getMessage(),e);}}
    public boolean xoa(String ma){try(Connection c=ConnectDB.getConnection()){return DeletePolicy.xoaHoacAn(c,"SELECT 1 FROM LichHen WITH (XLOCK, HOLDLOCK) WHERE maLichHen=? AND trangThai <> N'Đã xóa'",new String[]{"SELECT 1 FROM DichVu WHERE maLichHen=?","SELECT 1 FROM HoaDon WHERE maLichHen=?"},"UPDATE LichHen SET trangThai=N'Đã xóa' WHERE maLichHen=? AND trangThai <> N'Đã xóa'","DELETE FROM LichHen WHERE maLichHen=? AND trangThai <> N'Đã xóa'",ma);}catch(SQLException e){throw new IllegalStateException("Không thể xóa hoặc ẩn lịch hẹn: "+e.getMessage(),e);}}
    private void gan(PreparedStatement p,LichHen l,boolean update)throws SQLException{p.setString(1,l.getMaLichHen());p.setTimestamp(2,Timestamp.valueOf(l.getThoiGianHen()));p.setString(3,l.getTrangThai());p.setString(4,l.getMaNV().getMaNV());p.setString(5,l.getMaKH().getMaKH());p.setString(6,l.getMaThuCung().getMaThuCung());}
